from itertools import chain, islice
from collections.abc import Iterable


def _is_scalar(value):
    return isinstance(value, (str, bytes)) or not isinstance(value, Iterable)


def _flatten(matrix):
    """Flatten nested iterables until the first value of a dimension is a scalar."""
    it = iter(matrix)
    try:
        first = next(it)
    except StopIteration:
        return iter(())
    items = chain([first], it)
    if _is_scalar(first):
        return items
    return _flatten(chain.from_iterable(items))


def _build(flat, dims):
    """Lazily build nested tuples from the flat iterator, outermost dim first."""
    size = dims[0]
    if len(dims) == 1:
        return islice(flat, size)
    return _build_nested(flat, dims)


def _build_nested(flat, dims):
    size, rest = dims[0], dims[1:]
    for _ in range(size):
        if len(rest) == 1:
            group = tuple(islice(flat, rest[0]))
            if not group:
                return
        else:
            group = tuple(_build_nested(flat, rest))
            if not group:
                return
        yield group


def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]

    Each dimension is assumed to be uniform, either all arrays or all scalars.
    Flattening stops when the first value in a dimension is a scalar.
    Scalars are bytes, strings, and non-iterables.
    The reshape iterator stops when the requested shape is complete
    or when the input is exhausted, whichever comes first.

    """
    if isinstance(shape, int) and not isinstance(shape, bool):
        if shape <= 0:
            raise ValueError("shape must be a positive integer")
        if not isinstance(matrix, Iterable):
            raise TypeError("matrix must be iterable")
        return _reshape_cols(matrix, shape)

    if not isinstance(shape, Iterable) or isinstance(shape, (str, bytes)):
        raise TypeError("shape must be an integer or an iterable of integers")
    if not isinstance(matrix, Iterable):
        raise TypeError("matrix must be iterable")
    dims = tuple(shape)
    if not dims:
        raise ValueError("shape must not be empty")
    for d in dims:
        if not isinstance(d, int) or isinstance(d, bool):
            raise TypeError("shape dimensions must be integers")
        if d <= 0:
            raise ValueError("shape dimensions must be positive")
    return _reshape_dims(matrix, dims)


def _reshape_cols(matrix, cols):
    flat = chain.from_iterable(matrix)
    while True:
        row = tuple(islice(flat, cols))
        if not row:
            return
        yield row


def _reshape_dims(matrix, dims):
    flat = _flatten(matrix)
    yield from _build(flat, dims)
